get_handoff_spec <- function(position, mode) {
  spec <- model_handoff_registry[
    model_handoff_registry$position == position &
      model_handoff_registry$mode == mode,
  ]
  if (nrow(spec) == 0) {
    stop(
      paste0("No handoff spec found for ", position, " / ", mode, "."),
      call. = FALSE
    )
  }
  spec
}

