    dplyr::summarise(
      team_te_targets = sum(.data$targets, na.rm = TRUE),
      team_te_receptions = sum(.data$receptions, na.rm = TRUE),
      team_te_routes = sum(.data$routes, na.rm = TRUE),
      team_te_receiving_yards = sum(.data$receiving_yards, na.rm = TRUE),
