    utils::write.csv(tuning, tuning_path, row.names = FALSE, na = "")
    utils::write.csv(schedule, schedule_path, row.names = FALSE, na = "")
    utils::write.csv(matchup_context, matchup_path, row.names = FALSE, na = "")
